int main() {
    std::string line1, line2;
    std::getline(std::cin, line1);
    std::getline(std::cin, line2);

    // Replace all underscores with spaces and trim
    for (auto &ch : line2) {
        if (ch == '_') ch = ' ';
    }
    // Trim leading and trailing spaces
    size_t start = line2.find_first_not_of(' ');
    size_t end = line2.find_last_not_of(' ');
    std::string combined = (start == std::string::npos) ? "" : line2.substr(start, end - start + 1);

    // Extract inside parentheses
    std::stringstream insideParentheses;
    int flag = 0;
    for (char c : combined) {
        if (c == '(') {
            flag = 1;
        } else if (c == ')') {
            insideParentheses << ' ';
            flag = 0;
        } else if (flag == 1) {
            insideParentheses << c;
        }
    }
    std::string s = line2;
    size_t pos;
    while ((pos = s.find('(')) != std::string::npos) {
        size_t closePos = s.find(')', pos);
        if (closePos == std::string::npos) break;
        s = s.substr(0, pos) + " " + s.substr(closePos + 1);
    }
    // Replace multiple spaces with single space and trim
    std::string temp;
    std::istringstream iss(s);
    std::string token;
    std::vector<std::string> tokens;
    while (iss >> token) {
        tokens.push_back(token);
    }
    s = "";
    for (size_t i = 0; i < tokens.size(); ++i) {
        s += tokens[i];
        if (i != tokens.size() - 1) s += " ";
    }

    std::string ss = insideParentheses.str();
    // Replace multiple spaces with single space and trim
    std::istringstream iss2(ss);
    std::vector<std::string> inTokens;
    while (iss2 >> token) {
        inTokens.push_back(token);
    }
    ss = "";
    for (size_t i = 0; i < inTokens.size(); ++i) {
        ss += inTokens[i];
        if (i != inTokens.size() - 1) ss += " ";
    }

    // Split s and ss into words
    std::vector<std::string> outWords, inWords;
    std::istringstream issOut(s);
    while (issOut >> token) {
        outWords.push_back(token);
    }
    std::istringstream issIn(ss);
    while (issIn >> token) {
        inWords.push_back(token);
    }

    int maxLength = 0;
    for (const auto &word : outWords) {
        if ((int)word.length() > maxLength) {
            maxLength = word.length();
